import{_ as u,a0 as o,w as p,s as d,I as l,x as n,a1 as r,A as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const a=JSON.parse('{"title":"又一次 Mindcraft 事件？ | LCTT x X-CMD","titleTemplate":false,"description":"又一次 Mindcraft 事件？ | LCTT (201605) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"又一次 Mindcraft 事件？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"又一次 Mindcraft 事件？ | LCTT (201605) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201605/20151202 A new Mindcraft moment","title":"又一次 Mindcraft 事件？","tag":"201605","desc":""},"relativePath":"201605/20151202 A new Mindcraft moment.md","filePath":"[post].md"}'),f={name:"201605/20151202 A new Mindcraft moment.md"};function e(m,t,x,L,w,T){const i=o("Link");return p(),d("div",null,[t[30]||(t[30]=l("h1",{id:"又一次-mindcraft-事件",tabindex:"-1"},[n("又一次 Mindcraft 事件？ "),l("a",{class:"header-anchor",href:"#又一次-mindcraft-事件","aria-label":"Permalink to “又一次 Mindcraft 事件？”"},"​")],-1)),l("p",null,[t[2]||(t[2]=n("Linux 內核開發很少吸引像華盛頓郵報這樣主流媒體的關注，內核社區在安全方面進展的冗長功能列表就更少人看了。所以當",-1)),r(i,{href:"https://lwn.net/Articles/663338/"},{default:s(()=>[...t[0]||(t[0]=[n("這樣一個專題",-1)])]),_:1}),t[3]||(t[3]=n("發佈到網上，就吸引了很多人的注意（LCTT 譯註：華盛頓郵報發表了一篇很長的",-1)),r(i,{href:"http://www.washingtonpost.com/sf/business/2015/11/05/net-of-insecurity-the-kernel-of-the-argument/"},{default:s(()=>[...t[1]||(t[1]=[n("專題文章",-1)])]),_:1}),t[4]||(t[4]=n("，批評 Linux “沒有一個系統性的機制以在駭客之前發現和解決安全問題，或引入更新的防禦技術”，“Linux 內核開發社區沒有一個首席安全官”等等）。關於這篇文章有不同的反應，很多人認為這是對 Linux 直接的攻擊。文章背後的動機很難知道，但是從歷史經驗來看，它也可以看作對我們早就該前進的方向的一次非常必要的推動。",-1))]),l("p",null,[t[7]||(t[7]=n("回顧一件昏暗遙遠過去的事件 - 確切地説是在 1999 年 4 月。一家叫 Mindcraft 的分析公司發佈了一份",-1)),r(i,{href:"http://www.mindcraft.com/whitepapers/nts4rhlinux.html"},{default:s(()=>[...t[5]||(t[5]=[n("報告",-1)])]),_:1}),t[8]||(t[8]=n("顯示 Windows NT 在 Web 服務器開銷方面完勝 Red Hat Linux 5.2 加 Apache。Linux 社區，包括當時還",-1)),r(i,{href:"https://static.lwn.net/1999/features/MindCraft1.0.php3"},{default:s(()=>[...t[6]||(t[6]=[n("很年輕的 LWN",-1)])]),_:1}),t[9]||(t[9]=n("，對此反應很迅速而且強烈。這份報告是微軟資助的 FUD 的一部分，用來消除那些全球壟斷計劃的新興威脅。報告中所用的 Linux 系統有意配置成低性能，同時選擇了當時 Linux 並不能很好支持的硬件，等等。",-1))]),l("p",null,[t[11]||(t[11]=n("在大家稍微冷靜一點後，儘管如此，事實很明顯：Mindcraft 的人，不管什麼動機，説的也有一定道理。當時 Linux 確實在性能方面存在一些已經被充分認識到的問題。然後社區做了最正確的事情：我們坐下來解決問題。比如，單獨喚醒的調度器可以解決接受連接請求時的",-1)),r(i,{href:"https://en.wikipedia.org/wiki/Thundering_herd_problem"},{default:s(()=>[...t[10]||(t[10]=[n("驚羣問題",-1)])]),_:1}),t[12]||(t[12]=n("。其他很多小問題也都解決了。在差不多一年裏，內核在這類開銷方面的性能已經有了非常大的改善。",-1))]),t[31]||(t[31]=l("p",null,"這份 Mindcraft 的報告，某種意義上來説，往 Linux 屁股上踢了很有必要的一腳，推動整個社區去處理一些當時被忽略的事情。",-1)),t[32]||(t[32]=l("p",null,"華盛頓郵報的文章明顯以負面的看法看待 Linux 內核以及它的貢獻者。它隨意地混淆了內核問題和其他根本不是內核脆弱性引起的問題（比如，AshleyMadison.com 被黑）。不過供應商沒什麼興趣為他們的客户提供安全補丁的事實，就像一頭在房間裏巨象一樣明顯。還有謠言説這篇文章後面的黑暗勢力希望打擊一下 Linux 的勢頭。這些也許都是真的，但是也不能掩蓋一個簡單的事實，就是文章説的確實是真的。",-1)),t[33]||(t[33]=l("p",null,"我們會合理地測試並解決問題。而這些問題，不管是不是安全相關，能很快得到修復，然後再通過穩定更新的機制將這些補丁發佈給內核用户。比起外面很多應用程序（自由的和商業的），內核的支持工作做的非常好。但是指責我們解決問題的能力時卻遺漏了關鍵的一點：解決安全問題終究來説是一個打鼴鼠遊戲。總是會出來更多的鼴鼠，其中有一些在攻擊者發現並利用後很長時間我們都還不知道（所以沒法使勁打下去）。儘管 Linux 的商業支持已經非常努力地在將補丁傳遞給用户，這種問題還是會讓我們的用户很受傷 - 只是這並不是故意的。",-1)),l("p",null,[t[14]||(t[14]=n("關鍵是隻是解決問題並不夠，一些關心安全性的開發者也已經開始嘗試做些什麼。我們必須認識到，缺陷永遠都解決不完，所以要讓缺陷更難被發現和利用。這意思就是限制訪問內核信息，絕對不允許內核執行用户空間內存中的指令，讓內核去偵測整形溢出，以及 ",-1)),r(i,{href:"https://lwn.net/Articles/662219/"},{default:s(()=>[...t[13]||(t[13]=[n("Kee Cook 在十月底內核峯會的講話",-1)])]),_:1}),t[15]||(t[15]=n("中所提出的其他所有事情。其中許多技術被其他操作系統深刻理解並採用了；另外一些需要我們去創新。但是，如果我們想充分保護我們的用户免受攻擊，這些改變是必須要做的。",-1))]),t[34]||(t[34]=l("p",null,"為什麼內核還沒有引入這些技術？華盛頓郵報的文章堅定地指責開發社區，特別是 Linus Torvalds。內核社區的傳統就是相對安全性更側重於性能和功能，在需要犧牲性能來改善內核安全性時並不願意折衷處理。這些指責一定程度上是對的；好的一面是，因為問題的範圍變得清晰，態度看上去有所改善。Kee 的演講都聽進去了，而且很明顯讓開發者開始思考和討論這些問題了。",-1)),t[35]||(t[35]=l("p",null,"而被忽略的一點是，並不僅僅是 Linus 在拒絕有用的安全補丁。而是就沒有多少這種補丁在內核社區裏流傳。特別是，在這個領域工作的開發者就那麼些人，而且從沒有認真地嘗試把自己的工作整合到上游。要合併任何大的侵入性補丁，需要和內核社區一起工作，為這些改動編寫用例，將改動分割成方便審核的碎片，處理審核意見，等等。整個過程可能會有點無聊而且讓人沮喪，但這卻是內核維護的運作方式，而且很明顯只有這樣才能在長時間的開發中形成更有用更可維護的內核。",-1)),t[36]||(t[36]=l("p",null,"幾乎沒有人會走這個流程來將最新的安全技術引入內核。對於這類補丁可能收到的不利反應，有人覺得也許會導致“寒蟬效應”，但是這個説法並不充分：不管最初的反應有多麻煩，多年以來開發者已經合併了大量的改動。而少數安全開發者連試都沒試過。",-1)),t[37]||(t[37]=l("p",null,"他們為什麼不願意嘗試？一個比較明顯的答案是，幾乎沒有人會因此拿到報酬。幾乎所有引入內核的工作都由付費開發者完成，而且已經持續多年。公司能看到利潤的領域在內核裏都有大量的工作以及很好的進展。而公司覺得和它們沒關係的領域就不會這樣了。為實時 Linux 的開發找到贊助支持的困難就是很明顯的例子。其他領域，比如文檔，也在慢慢蕭條。安全性很明顯也屬於這類領域。可能有很多原因導致 Linux 落後於防禦式安全技術，但是其中最關鍵的一條是，靠 Linux 賺錢的公司沒有重視這些技術的開發和應用。",-1)),l("p",null,[t[17]||(t[17]=n("有跡象顯示局面已有所轉變。越來越多的開發人員開始關注安全相關問題，儘管對他們工作的商業支持還仍然不夠。對於安全相關的改變已經沒有之前那樣的下意識反應了。像",-1)),r(i,{href:"https://lwn.net/Articles/663361/"},{default:s(()=>[...t[16]||(t[16]=[n("內核自我保護項目",-1)])]),_:1}),t[18]||(t[18]=n("這樣，已經開始把現有的安全技術集成進入內核了。",-1))]),t[38]||(t[38]=l("p",null,"我們還有很長的路要走，但是，如果能有一些支持以及正確的觀念，短期內就能有很大的進展。內核社區在確定了自己的想法後可以做到很讓人驚歎的事情。幸運的是，華盛頓郵報的文章將有助於提供形成這種想法的必要動力。以歷史的角度看，我們很可能會把這次事件看作一個轉折點，我們最終被倒逼着去完成之前很明確需要做的事情。Linux 不應該再繼續講述這個安全不合格的故事了。",-1)),t[39]||(t[39]=l("hr",null,null,-1)),l("p",null,[t[20]||(t[20]=n("via: ",-1)),r(i,{href:"https://lwn.net/Articles/663474/"},{default:s(()=>[...t[19]||(t[19]=[n("https://lwn.net/Articles/663474/",-1)])]),_:1})]),l("p",null,[t[23]||(t[23]=n("作者：Jonathan Corbet 譯者：",-1)),r(i,{href:"https://github.com/zpl1025"},{default:s(()=>[...t[21]||(t[21]=[n("zpl1025",-1)])]),_:1}),t[24]||(t[24]=n(" 校對：",-1)),r(i,{href:"https://github.com/wxy"},{default:s(()=>[...t[22]||(t[22]=[n("wxy",-1)])]),_:1})]),l("p",null,[t[27]||(t[27]=n("本文由 ",-1)),r(i,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[25]||(t[25]=[n("LCTT",-1)])]),_:1}),t[28]||(t[28]=n(" 原創編譯，",-1)),r(i,{href:"https://linux.cn/"},{default:s(()=>[...t[26]||(t[26]=[n("Linux中國",-1)])]),_:1}),t[29]||(t[29]=n(" 榮譽推出",-1))])])}const g=u(f,[["render",e]]);export{a as __pageData,g as default};
